function openDetail(id){
  var p = projects.filter(function(x){ return x.id===id; })[0];
  if(!p) return;

  /* LEFT — condensed project description, stays fixed while the right side scrolls */
  var left = '';
  left += '<div class="detail-eyebrow mono">PROJECT '+p.index+'</div>';
  left += '<div class="detail-title">'+p.title+'</div>';
  left += p.subtitle ? '<p class="detail-sub">'+p.subtitle+'</p>' : '';

  left += '<div class="detail-meta-list">'+
    '<div class="row"><span class="k mono">TYPE</span><span class="v">'+p.type+'</span></div>'+
    '<div class="row"><span class="k mono">ROLE</span><span class="v">'+p.role+'</span></div>'+
    '<div class="row"><span class="k mono">DURATION</span><span class="v">'+p.duration+'</span></div>'+
    '<div class="row"><span class="k mono">TOOLS</span><span class="v">'+p.tools+'</span></div>'+
  '</div>';

  if(p.background){
    left += '<div class="mini-block"><span class="k mono">OVERVIEW</span><p>'+p.background+
      (p.goal ? ' '+p.goal : '')+'</p></div>';
  }
  if(p.painPoints && p.painPoints.length){
    left += '<div class="mini-block"><span class="k mono">PROBLEM</span><ul class="mini-list">'+
      p.painPoints.map(function(pt){ return '<li>'+pt.desc+'</li>'; }).join('')+
    '</ul></div>';
  }
  if(p.solution){
    left += '<div class="mini-block"><span class="k mono">SOLUTION</span><p>'+p.solution.summary+'</p></div>';
  }
  if(p.finalNote){
    left += '<div class="mini-block"><span class="k mono">FINAL</span><p>'+p.finalNote+'</p></div>';
  }

  /* RIGHT — scrolling stack of project imagery */
  var right = '';
  if(p.detailImages){
    right += p.detailImages.map(function(g){ return '<img src="'+g+'" alt="'+p.title+' detail">'; }).join('');
  } else {
    if(p.coverImage){ right += '<img src="'+p.coverImage+'" alt="'+p.title+' cover">'; }
    if(p.fullImage){ right += '<img src="'+p.fullImage+'" alt="'+p.title+' case study">'; }
    if(p.gallery){
      right += p.gallery.map(function(g){ return '<img src="'+g+'" alt="'+p.title+' visual">'; }).join('');
    }
    if(!p.coverImage && !p.fullImage && !p.gallery && p.uiScreens){
      right += p.uiScreens.map(function(s){
        return '<div class="media-frame" style="aspect-ratio:4/3;">'+
          '<div class="ph-label mono">'+s.name+'</div><div class="ratio-tag mono">4:3</div>'+
        '</div><div class="shot-caption mono">'+s.name+'</div>';
      }).join('');
    }
  }

  var rightClass = 'detail-split-right' + (p.seamlessDetail ? ' seamless' : '');
  detailContent.innerHTML =
    '<div class="detail-split">'+
      '<div class="detail-split-left">'+left+'</div>'+
      '<div class="'+rightClass+'">'+right+'</div>'+
    '</div>';

  detailPanel.scrollTop = 0;
  detailPanel.classList.add('open');
  document.body.classList.add('lock');
  try{ history.pushState({ detail:id }, '', '#project-'+id); }catch(err){ /* sandboxed preview: ignore */ }
}
function closeDetail(){
  detailPanel.classList.remove('open');
  document.body.classList.remove('lock');
  if(location.hash.indexOf('project-')>-1){
    try{ history.pushState({}, '', location.pathname+location.search); }catch(err){ /* sandboxed preview: ignore */ }
  }
}
document.getElementById('detailClose').addEventListener('click', closeDetail);
document.getElementById('detailBack').addEventListener('click', closeDetail);
window.addEventListener('popstate', function(){
  if(location.hash.indexOf('project-') === -1){ closeDetail(); }
});
