/* explicit scroll-to-section for EVERY in-page hash link (header, fs-menu,
   hero CTA buttons like VIEW WORK / CONTACT, etc.) — bulletproof against
   fixed-header overlap and any iframe/host quirks with native hash
   navigation, which can otherwise hijack the click into a real page
   navigation instead of just scrolling. Always resolves to a real scroll. */
document.querySelectorAll('a[href^="#"]').forEach(function(link){
  link.addEventListener('click', function(e){
    var href = link.getAttribute('href');
    if(!href || href.length < 2) return;
    var target;
    try{ target = document.querySelector(href); }catch(err){ return; }
    if(!target) return;
    e.preventDefault();
    var headerOffset = 90;
    var y = target.getBoundingClientRect().top + window.pageYOffset - headerOffset;
    window.scrollTo({ top: Math.max(0, y), behavior: 'smooth' });
    try{ history.pushState(null, '', href); }catch(err){ /* sandboxed preview: ignore */ }
  });
});

/* résumé PDF — downloaded directly from an in-memory Blob, no new tab or
   window is ever opened. window.open()/target="_blank" is intentionally
   avoided here: some preview/sandbox environments intercept new browsing
   contexts, so instead a temporary <a download> anchor is clicked
   programmatically, which triggers a same-page file save. */
var resumeLink = document.getElementById('resumeLink');
if(resumeLink){
  resumeLink.addEventListener('click', function(e){
    e.preventDefault();
    try{
      var byteChars = atob(resumeBase64);
      var byteNumbers = new Array(byteChars.length);
      for(var i=0;i<byteChars.length;i++){ byteNumbers[i] = byteChars.charCodeAt(i); }
      var byteArray = new Uint8Array(byteNumbers);
      var blob = new Blob([byteArray], { type:'application/pdf' });
      var url = URL.createObjectURL(blob);
      var tempA = document.createElement('a');
      tempA.href = url;
      tempA.download = 'JUNG_EUNJI_Resume.pdf';
      document.body.appendChild(tempA);
      tempA.click();
      document.body.removeChild(tempA);
      setTimeout(function(){ URL.revokeObjectURL(url); }, 4000);
    }catch(err){ /* sandboxed preview / blob unsupported: nothing further to do */ }
  });
}

