/* =============================================================
   CUSTOM CURSOR
============================================================= */
if(!isTouch){
  var dot = document.querySelector('.cursor-dot');
  var ring = document.querySelector('.cursor-ring');
  var ringLabel = ring.querySelector('span');
  var mx=0,my=0, rx=0, ry=0;
  window.addEventListener('mousemove', function(e){
    mx=e.clientX; my=e.clientY;
    dot.style.left=mx+'px'; dot.style.top=my+'px';
  });
  (function loop(){
    rx += (mx-rx)*0.16; ry += (my-ry)*0.16;
    ring.style.left=rx+'px'; ring.style.top=ry+'px';
    requestAnimationFrame(loop);
  })();
  function setCursorState(el){
    var mode = el ? el.getAttribute('data-cursor') : null;
    ring.classList.remove('grow','btn');
    if(mode==='view'){ ring.classList.add('grow'); ringLabel.textContent='VIEW'; }
    else if(mode==='open'){ ring.classList.add('btn'); ringLabel.textContent='OPEN →'; }
    else if(el){ ring.classList.add('grow'); ringLabel.textContent=''; }
  }
  document.addEventListener('mouseover', function(e){
    var el = e.target.closest('[data-cursor], a, button, .project-card, .nav-link');
    if(el) setCursorState(el);
  });
  document.addEventListener('mouseout', function(e){
    var el = e.target.closest('[data-cursor], a, button, .project-card, .nav-link');
    if(el){ ring.classList.remove('grow','btn'); ringLabel.textContent=''; }
  });
}

