/* =============================================================
   THREE.JS SCENE
============================================================= */
var canvas = document.getElementById('webgl');
var renderer = new THREE.WebGLRenderer({ canvas:canvas, antialias:true, alpha:true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, isMobile?1.5:2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setClearColor(0x000000,0);

var scene = new THREE.Scene();
var camera = new THREE.PerspectiveCamera(42, window.innerWidth/window.innerHeight, 0.1, 200);
camera.position.set(0,0,7);

scene.add(new THREE.AmbientLight(0x999ba0,0.5));
var key = new THREE.DirectionalLight(0xffffff,1.4); key.position.set(6,8,6); scene.add(key);
var rim = new THREE.PointLight(0xdfe6ee,2.2,60); rim.position.set(-8,-4,4); scene.add(rim);
var fillLight = new THREE.PointLight(0xffffff,1.1,60); fillLight.position.set(4,-6,-6); scene.add(fillLight);

function buildEnvironment(){
  var pmrem = new THREE.PMREMGenerator(renderer);
  pmrem.compileEquirectangularShader();
  var envScene = new THREE.Scene();
  var c = document.createElement('canvas'); c.width=4; c.height=256;
  var ctx = c.getContext('2d');
  var grad = ctx.createLinearGradient(0,0,0,256);
  grad.addColorStop(0.00,'#eef0f3'); grad.addColorStop(0.18,'#3a3d43');
  grad.addColorStop(0.35,'#0a0a0c'); grad.addColorStop(0.50,'#4a4e57');
  grad.addColorStop(0.65,'#0a0a0c'); grad.addColorStop(0.82,'#3a3d43');
  grad.addColorStop(1.00,'#d6d9de');
  ctx.fillStyle=grad; ctx.fillRect(0,0,4,256);
  var tex = new THREE.CanvasTexture(c);
  tex.mapping = THREE.EquirectangularReflectionMapping; tex.needsUpdate = true;
  var sphere = new THREE.Mesh(new THREE.SphereGeometry(60,24,24), new THREE.MeshBasicMaterial({map:tex, side:THREE.BackSide}));
  envScene.add(sphere);
  var panelGeo = new THREE.PlaneGeometry(10,26);
  var panelMat = new THREE.MeshBasicMaterial({color:0xffffff});
  [[-18,4,-8],[18,-2,-10],[0,22,-14],[0,-20,10]].forEach(function(p){
    var panel = new THREE.Mesh(panelGeo, panelMat);
    panel.position.set(p[0],p[1],p[2]); panel.lookAt(0,0,0); envScene.add(panel);
  });
  var rt = pmrem.fromScene(envScene, 0.035);
  pmrem.dispose();
  return rt.texture;
}
var envMap = buildEnvironment();
scene.environment = envMap;

function chromeMat(opts){
  opts = opts || {};
  return new THREE.MeshStandardMaterial({
    color: opts.color || 0xcfd2d8, metalness:1.0,
    roughness: opts.roughness!==undefined?opts.roughness:0.22,
    envMap: envMap, envMapIntensity:1.4
  });
}
var seg = isMobile ? 0.5 : 1;

/* HERO — polished chrome gaiwan, deconstructed / levitating 3-piece set
   (saucer, bowl, lid+knob), each a lathed metal shell */
function latheChrome(points, opts){
  opts = opts || {};
  var pts = points.map(function(p){ return new THREE.Vector2(p[0], p[1]); });
  var geo = new THREE.LatheGeometry(pts, Math.round(56*seg));
  var mat = chromeMat({ roughness: opts.roughness!==undefined?opts.roughness:0.12, color: opts.color });
  mat.side = THREE.DoubleSide;
  return new THREE.Mesh(geo, mat);
}

var heroGroup = new THREE.Group();

/* 받침 saucer — shallow dish with a raised rim */
var gaiwanSaucer = latheChrome([
  [0.00,0.000],[0.16,0.006],[0.46,0.020],[0.76,0.050],
  [0.99,0.100],[1.16,0.165],[1.10,0.195]
], { roughness:0.15 });
gaiwanSaucer.position.set(-0.16, -0.95, 0.08);
gaiwanSaucer.rotation.z = -0.06;
heroGroup.add(gaiwanSaucer);

/* 찻잔 bowl — flared cup with an open rim, hollow interior visible */
var gaiwanBowl = latheChrome([
  [0.02,-0.52],[0.12,-0.50],[0.30,-0.42],[0.50,-0.28],
  [0.68,-0.08],[0.82, 0.14],[0.90, 0.34],[0.93, 0.48],[0.88, 0.56]
], { roughness:0.10, color:0xd6d9de });
gaiwanBowl.position.set(-0.36, 0, -0.06);
gaiwanBowl.rotation.z = 0.13;
heroGroup.add(gaiwanBowl);

/* 뚜껑 lid — dome shell (concave underside) + knob, floats above the bowl */
var gaiwanLid = new THREE.Group();
var lidShell = latheChrome([
  [0.95,-0.02],[0.90,0.05],[0.75,0.14],[0.55,0.20],
  [0.35,0.24],[0.18,0.26],[0.10,0.27],[0.00,0.28]
], { roughness:0.10 });
gaiwanLid.add(lidShell);
var knobStem = new THREE.Mesh(new THREE.CylinderGeometry(0.05,0.07,0.12,Math.round(24*seg)), chromeMat({roughness:0.14}));
knobStem.position.y = 0.34;
gaiwanLid.add(knobStem);
var knobCap = new THREE.Mesh(new THREE.SphereGeometry(0.1,Math.round(24*seg),Math.round(24*seg)), chromeMat({roughness:0.08}));
knobCap.position.y = 0.43;
gaiwanLid.add(knobCap);
gaiwanLid.position.set(0.58, 0.9, -0.08);
gaiwanLid.rotation.z = -0.26;
heroGroup.add(gaiwanLid);

heroGroup.scale.setScalar(isMobile ? 0.95 : 1.3);
scene.add(heroGroup);

/* WORK 01 — Chrome Ring */
var ringGroup = new THREE.Group();
var ringOuter = new THREE.Mesh(new THREE.TorusGeometry(1.5,0.2,32,Math.round(140*seg)), chromeMat({roughness:0.14}));
var ringInner = new THREE.Mesh(new THREE.TorusGeometry(0.85,0.06,16,Math.round(100*seg)), chromeMat({roughness:0.3,color:0x9a9ea6}));
ringInner.rotation.x = Math.PI/2.3;
ringGroup.add(ringOuter, ringInner);
scene.add(ringGroup);

/* WORK 02 — Metallic Sphere with satellites */
var sphereGroup = new THREE.Group();
var sphereMain = new THREE.Mesh(new THREE.SphereGeometry(1.35, Math.round(64*seg), Math.round(64*seg)), chromeMat({roughness:0.1}));
sphereGroup.add(sphereMain);
var satOrbit = new THREE.Group();
var sat1 = new THREE.Mesh(new THREE.SphereGeometry(0.14,24,24), chromeMat({roughness:0.25}));
sat1.position.set(2.3,0,0);
var sat2 = new THREE.Mesh(new THREE.SphereGeometry(0.09,24,24), chromeMat({roughness:0.25}));
sat2.position.set(-1.9,0.5,0.4);
satOrbit.add(sat1, sat2);
sphereGroup.add(satOrbit);
